import{_ as e,o as r,c as o,a2 as s}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"运行状态","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/service-status.md","filePath":"zh-CN/user-guide/settings/service-status.md","lastUpdated":1787586465000}'),a={name:"zh-CN/user-guide/settings/service-status.md"};function i(n,t,l,g,d,c){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="运行状态" tabindex="-1">运行状态 <a class="header-anchor" href="#运行状态" aria-label="Permalink to &quot;运行状态&quot;">​</a></h1><p>运行状态页面集中监控 Lertaro 核心后台服务的生命周期健康度，并内置了面向 Service、App 与 Hook 三大核心进程的高性能实时日志查看器。页面路径为<strong>设置 → 运行状态</strong>。</p><h2 id="_1-服务状态与控制" tabindex="-1">1. 服务状态与控制 <a class="header-anchor" href="#_1-服务状态与控制" aria-label="Permalink to &quot;1. 服务状态与控制&quot;">​</a></h2><p>页面顶部展示后台提权索引服务的运行状态卡片：</p><ul><li><strong>实时状态显示</strong>： <ul><li><strong>就绪（Ready）</strong>：服务运行健康，实时呈现当前已索引的物理文件与文件夹总条目数。</li><li><strong>索引中（Indexing）</strong>：正在执行初始构建或全量增量更新，显示动态进度指示器。</li><li><strong>安装中（Installing）</strong>：正在注册并部署 Windows 后台服务。</li><li><strong>错误（Error）</strong>：服务未运行或遇到异常中断，显示醒目的警告标记与错误描述。</li></ul></li><li><strong>服务自愈与安装按钮</strong>：当且仅当后台服务尚未安装或由于系统权限受损进入异常状态时，页面会提供<strong>安装并启动服务</strong>按钮；在服务健康运行期间，系统会维持后台持续常驻，避免误操作导致索引中断。</li></ul><h2 id="_2-三进程实时日志查看器" tabindex="-1">2. 三进程实时日志查看器 <a class="header-anchor" href="#_2-三进程实时日志查看器" aria-label="Permalink to &quot;2. 三进程实时日志查看器&quot;">​</a></h2><p>页面下方提供了内置日志终端，分为三个独立的标签页，分别对应 Lertaro 运行的三大进程：</p><ul><li><strong>App 标签页</strong>：记录前台 WPF 用户界面、搜索交互、快捷键响应与窗口渲染相关的操作日志。</li><li><strong>Hook 标签页</strong>：记录低级全局键盘钩子独立进程（<code>Lertaro.Hook.exe</code>）的按键捕获与进程隔离状态。</li><li><strong>Service 标签页</strong>：记录提权 Windows 后台服务（<code>Lertaro.Service.exe</code>）的 USN 日志解析、磁盘遍历、内存树构建与 IPC 通信日志。</li></ul><h3 id="过滤与日志清理功能" tabindex="-1">过滤与日志清理功能 <a class="header-anchor" href="#过滤与日志清理功能" aria-label="Permalink to &quot;过滤与日志清理功能&quot;">​</a></h3><ul><li><strong>日志等级过滤</strong>：下拉框支持筛选“全部 / 错误 / 警告 / 信息 / 调试”，日志行按严重等级自动呈现不同的颜色标记。</li><li><strong>实时搜索过滤</strong>：在搜索框中输入关键词可瞬间对当前日志内容进行全文过滤，并与等级过滤条件叠加生效。</li><li><strong>安全清空日志</strong>：点击<strong>清空日志</strong>按钮可清理当前标签页的历史日志输出。清理 Service 日志时会自动通过提权服务代理安全截断，无需手动提升管理员权限。</li></ul>',10)])])}const _=e(a,[["render",i]]);export{h as __pageData,_ as default};
